theory.example:
int main() {
  int width = 2;
  const int& view = width;
  int next = view + 1;
  (void)next;
}
// view — lvalue: обозначает width, хотя запрещает запись через view.
// view + 1 — prvalue int, вычисление отдельного значения.

references.example:
int main() {
  int height = 7;
  int wider = height + 5;
  (void)wider;
}
// height обозначает объект; height + 5 вычисляет новое значение int.
